document.addEventListener("DOMContentLoaded", () => {
  document.querySelectorAll("[data-project-gallery]").forEach((gallery) => {
    const mainImage = gallery.querySelector("[data-gallery-main]");
    const caption = gallery.querySelector("[data-gallery-caption]");
    const previous = gallery.querySelector("[data-gallery-previous]");
    const next = gallery.querySelector("[data-gallery-next]");
    const thumbnails = Array.from(gallery.querySelectorAll("[data-gallery-image]"));
    let activeIndex = Math.max(
      0,
      thumbnails.findIndex((thumbnail) => thumbnail.classList.contains("is-active")),
    );

    if (!mainImage || thumbnails.length === 0) return;

    const showImage = (index, scrollThumbnail = false) => {
      activeIndex = (index + thumbnails.length) % thumbnails.length;
      const activeThumbnail = thumbnails[activeIndex];

      mainImage.src = activeThumbnail.dataset.galleryImage;
      mainImage.alt = activeThumbnail.dataset.galleryAlt || "";
      if (caption) caption.textContent = activeThumbnail.dataset.galleryCaption || "";

      thumbnails.forEach((thumbnail, thumbnailIndex) => {
        const isActive = thumbnailIndex === activeIndex;
        thumbnail.classList.toggle("is-active", isActive);
        thumbnail.setAttribute("aria-selected", String(isActive));
        thumbnail.tabIndex = isActive ? 0 : -1;
      });

      if (scrollThumbnail) {
        activeThumbnail.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "center" });
      }
    };

    thumbnails.forEach((thumbnail, index) => {
      thumbnail.addEventListener("click", () => showImage(index, true));
    });

    if (previous) previous.addEventListener("click", () => showImage(activeIndex - 1, true));
    if (next) next.addEventListener("click", () => showImage(activeIndex + 1, true));

    showImage(activeIndex);
  });
});
